import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    v = int(input[2])

    if m < n - 1:
        print(-1)
        return

    # Create a star graph with v as the center
    edges = []
    for i in range(1, n + 1):
        if i != v:
            edges.append((v, i))

    # Add extra edges if needed
    current_edges = n - 1
    extra_edges_needed = m - current_edges
    additional_edges = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if len(edges) == m:
                break
            if i != v and j != v:
                edges.append((i, j))
                additional_edges += 1
        if len(edges) == m:
            break

    if len(edges) < m:
        print(-1)
    else:
        for edge in edges:
            print(edge[0], edge[1])

if __name__ == "__main__":
    main()
